const toKey = ([x, y]: Cell): string => `${x},${y}`;
const fromKey = (key: string): Cell => {
  const [x, y] = key.split(",").map(Number);
  return [x, y];
};

function countLiveNeighbors(liveCells: Cell[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const [x, y] of liveCells) {
    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
      const key = toKey([x + dx, y + dy]);
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
  }
  return counts;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const aliveKeys = new Set(liveCells.map(toKey));
  const neighborCounts = countLiveNeighbors(liveCells);
  const survivesOrIsBorn = ([key, count]: [string, number]): boolean =>
    count === 3 || (count === 2 && aliveKeys.has(key));
  return Array.from(neighborCounts).filter(survivesOrIsBorn).map(([key]) => fromKey(key));
}

