const toKey = ([x, y]: Cell): string => `${x},${y}`;

type NeighborEntry = { cell: Cell; count: number };

function countLiveNeighbors(liveCells: Cell[]): Map<string, NeighborEntry> {
  const counts = new Map<string, NeighborEntry>();
  for (const [x, y] of liveCells) {
    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
      const neighbor: Cell = [x + dx, y + dy];
      const key = toKey(neighbor);
      const existing = counts.get(key);
      if (existing) existing.count += 1;
      else counts.set(key, { cell: neighbor, count: 1 });
    }
  }
  return counts;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const aliveKeys = new Set(liveCells.map(toKey));
  const survivesOrIsBorn = (key: string, count: number): boolean =>
    count === 3 || (count === 2 && aliveKeys.has(key));
  const result: Cell[] = [];
  for (const [key, { cell, count }] of countLiveNeighbors(liveCells)) {
    if (survivesOrIsBorn(key, count)) result.push(cell);
  }
  return result;
}

