const toKey = ([x, y]: Cell): string => `${x},${y}`;

function countLiveNeighbors(liveCells: Cell[]): Map<string, { cell: Cell; count: number }> {
  const counts = new Map<string, { cell: Cell; count: number }>();
  for (const [x, y] of liveCells) {
    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
      const cell: Cell = [x + dx, y + dy];
      const key = toKey(cell);
      counts.set(key, { cell, count: (counts.get(key)?.count ?? 0) + 1 });
    }
  }
  return counts;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const aliveKeys = new Set(liveCells.map(toKey));
  const survivesOrIsBorn = (key: string, count: number): boolean =>
    count === 3 || (count === 2 && aliveKeys.has(key));
  return Array.from(countLiveNeighbors(liveCells))
    .filter(([key, { count }]) => survivesOrIsBorn(key, count))
    .map(([, { cell }]) => cell);
}
